//! 🎭️ Both actual guest export families borrow one paid original actor context and retain failed outputs.
use super::*;
use crate::component::wasip2::exports::semio::framework::reactor as Wire;
use semio_framework::kernel;
use std::cell::RefCell;
use crate::component::wasip2::exports::semio::framework::jobs as JobsWire;

crate::component_persistent_local!{
 static ORIGINAL_ACTOR_ENTRY:RefCell<OriginalActorGuestEntry>=RefCell::new(OriginalActorGuestEntry::new());
 static ORIGINAL_ACTOR_RECEIPT:RefCell<OriginalActorFixedReceipt>=RefCell::new(OriginalActorFixedReceipt::empty());
 static ORIGINAL_WIT_OUTPUT:RefCell<ManuallyDrop<Option<Wire::TurnResult>>>=RefCell::new(ManuallyDrop::new(None));
 static ORIGINAL_OWNED_OUTPUT:RefCell<ManuallyDrop<Option<kernel::TurnResult>>>=RefCell::new(ManuallyDrop::new(None));
}
fn busy()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original actor export remains checked out")}
fn with_entry<T>(body:impl FnOnce(&mut OriginalActorGuestEntry)->T)->Result<T,ValueError>{ORIGINAL_ACTOR_ENTRY.with(|original|original.try_borrow_mut().map(|mut original|body(&mut original)).map_err(|_|busy()))}
fn step_budget(input:RetainedTurnInput,fuel:u64,deadline_us:u64)->Result<StepBudget,ValueError>{input.validate()?;Ok(StepBudget::new(fuel,deadline_us,input.grant))}
fn native_input(input:Wire::RetainedTurnInput)->Result<RetainedTurnInput,ValueError>{let extent=|value:u64|usize::try_from(value).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"original actor wire extent exceeds native address space"));let grant=input.grant;let original=RetainedTurnInput{operation:input.operation,generation:input.generation,epoch:input.epoch,grant:semio_framework_value::RetainedCloneGrant{maximum_items:extent(grant.maximum_items)?,maximum_copy_bytes:extent(grant.maximum_copy_bytes)?,maximum_capacity_bytes:extent(grant.maximum_capacity_bytes)?,maximum_release_bytes:extent(grant.maximum_release_bytes)?,maximum_depth:extent(grant.maximum_depth)?}};original.validate()?;Ok(original)}
fn progress(original:RetainedCloneProgress)->Wire::RetainedProgress{Wire::RetainedProgress{copied_items:original.copied_items as u64,copied_bytes:original.copied_bytes as u64,retained_capacity_bytes:original.retained_capacity_bytes as u64,released_bytes:original.released_bytes as u64}}
fn kind(original:ValueRefusalKind)->Wire::ActorAuthorityRefusal{match original{ValueRefusalKind::InvalidValue=>Wire::ActorAuthorityRefusal::InvalidValue,ValueRefusalKind::Canceled=>Wire::ActorAuthorityRefusal::Canceled,ValueRefusalKind::OwnershipLimit=>Wire::ActorAuthorityRefusal::OwnershipLimit,ValueRefusalKind::AllocationFailed=>Wire::ActorAuthorityRefusal::AllocationFailed,ValueRefusalKind::WorkLimit=>Wire::ActorAuthorityRefusal::WorkLimit,ValueRefusalKind::DepthLimit=>Wire::ActorAuthorityRefusal::DepthLimit,ValueRefusalKind::UnsupportedOwner=>Wire::ActorAuthorityRefusal::UnsupportedOwner,ValueRefusalKind::InvariantViolated=>Wire::ActorAuthorityRefusal::InvariantViolated}}
fn failure(input:Wire::RetainedTurnInput,spent:RetainedCloneProgress,work_units_spent:u64,authority:Option<ValueRefusalKind>)->Wire::ActorCallRefusal{Wire::ActorCallRefusal{input,spent:progress(spent),work_units_spent,failure:authority.map(|original|Wire::ActorCallFailure::Authority(kind(original))).unwrap_or(Wire::ActorCallFailure::Semantic)}}
fn outputs_held()->bool{ORIGINAL_WIT_OUTPUT.with(|output|output.borrow().is_some())||ORIGINAL_OWNED_OUTPUT.with(|output|output.borrow().is_some())}
/// 🌱️ Empty admission cannot receive or consume the original Host event batch.
pub fn admit_wit(input:Wire::RetainedTurnInput)->Wire::ActorAdmissionCall{let original=(||{let native=native_input(input)?;with_entry(|entry|OriginalActorAdmissionReply::borrow_original(&entry.admit_step(native)))})();match original{Ok(reply)=>Wire::ActorAdmissionCall{input,spent:progress(reply.spent),ready:reply.ready,refusal:reply.refusal.map(kind)},Err(error)=>Wire::ActorAdmissionCall{input,spent:progress(error.retained_progress()),ready:false,refusal:Some(kind(error.kind))}}}
/// ♻️ Refused semantic outputs remain in original custody until their actual retirement producer exists.
pub fn close_wit(input:Wire::RetainedTurnInput)->Wire::ActorContextCloseCall{if outputs_held()||crate::reactor::jobs::has_owned_jobs(input.operation,input.generation){return Wire::ActorContextCloseCall{input,spent:progress(Default::default()),complete:false,blocked:true,refusal:None}}let original=(||{let native=native_input(input)?;with_entry(|entry|OriginalActorCloseReply::borrow_original(&entry.close_step(native)))})();match original{Ok(reply)=>Wire::ActorContextCloseCall{input,spent:progress(reply.spent),complete:reply.complete,blocked:reply.blocked,refusal:reply.refusal.map(kind)},Err(error)=>Wire::ActorContextCloseCall{input,spent:progress(error.retained_progress()),complete:false,blocked:false,refusal:Some(kind(error.kind))}}}
/// 🤝️ A successful reservation releases the same output; every authority refusal retains it.
pub fn poll_wit<PA:crate::plugin_app::PluginApp+'static>(runtime:&crate::plugin_runtime::PluginRuntime<PA>,events:Vec<Wire::Event>,budget:Wire::Budget)->Result<Wire::TurnResult,Wire::ActorCallRefusal>{
 let input=budget.retained;let mut spent=Default::default();let mut work_units_spent=0;let mut semantic=false;
 let admitted=crate::operation_authority::with_actor_operation_authority(|identity|{let native=native_input(input)?;let step=step_budget(native,budget.fuel,budget.deadline_us)?;if outputs_held(){return Err(busy())}let call=with_entry(|entry|entry.dispatch_value_step(native,step,&mut spent,original_job_clock,|cx|crate::plugin_runtime::drive_self_waking_ready(crate::reactor::poll(runtime,events,budget,identity,cx))))?;spent=call.receipt_spent;work_units_spent=call.work_units_spent;match call.result{Ok(mut output)=>{output.fuel_used=work_units_spent;ORIGINAL_WIT_OUTPUT.with(|pending|**pending.borrow_mut()=Some(output));call.input.return_original(spent)?;ORIGINAL_WIT_OUTPUT.with(|pending|{let pending=pending.borrow();let output=pending.as_ref().unwrap();crate::operation_authority::return_walk::walk_turn(output,&mut |kind,count|{let code=crate::component::wasip2::semio::framework::pure::operation_reserve_return(kind,count as u64);if code==0{Ok(())}else{Err(crate::operation_authority::refusal(code))}})})},Err(OriginalActorEntryFailure::Authority(error))=>Err(error),Err(OriginalActorEntryFailure::Semantic)=>{semantic=true;Ok(())}}});
 match admitted{Err(error)=>Err(failure(input,spent,work_units_spent,Some(error.kind))),Ok(())if semantic=>Err(failure(input,spent,work_units_spent,None)),Ok(())=>ORIGINAL_WIT_OUTPUT.with(|pending|pending.borrow_mut().take().ok_or_else(||failure(input,spent,work_units_spent,Some(ValueRefusalKind::InvariantViolated))))}
}
pub fn admit_owned(input:RetainedTurnInput)->u64{let reply=with_entry(|entry|OriginalActorAdmissionReply::borrow_original(&entry.admit_step(input))).unwrap_or_else(|error|OriginalActorAdmissionReply{input,spent:error.retained_progress(),ready:false,refusal:Some(error.kind)});return_fixed(OriginalActorFixedCall{input,spent:reply.spent,work_units_spent:0,kind:OriginalActorFixedKind::Admission{ready:reply.ready,refusal:reply.refusal}})}
pub fn close_owned(input:RetainedTurnInput)->u64{if outputs_held()||crate::reactor::jobs::has_owned_jobs(input.operation,input.generation){return return_fixed(OriginalActorFixedCall{input,spent:Default::default(),work_units_spent:0,kind:OriginalActorFixedKind::Close{complete:false,blocked:true,refusal:None}})}let reply=with_entry(|entry|OriginalActorCloseReply::borrow_original(&entry.close_step(input))).unwrap_or_else(|error|OriginalActorCloseReply{input,spent:error.retained_progress(),complete:false,blocked:false,refusal:Some(error.kind)});return_fixed(OriginalActorFixedCall{input,spent:reply.spent,work_units_spent:0,kind:OriginalActorFixedKind::Close{complete:reply.complete,blocked:reply.blocked,refusal:reply.refusal}})}
fn return_fixed(call:OriginalActorFixedCall)->u64{ORIGINAL_ACTOR_RECEIPT.with(|original|{let mut original=original.borrow_mut();original.write(call);u64::from(original.bytes().as_ptr()as usize as u32)|(112u64<<32)})}
/// 📤️ The original fixed result is resident instance storage, so deallocation releases only its loan.
pub fn fixed_receipt_pointer(pointer:u32,length:u32)->bool{length==112&&ORIGINAL_ACTOR_RECEIPT.with(|original|original.borrow().bytes().as_ptr()as usize as u32==pointer)}
pub fn poll_owned<PA:crate::plugin_app::PluginApp+'static>(runtime:&crate::plugin_runtime::PluginRuntime<PA>,input:crate::owned_abi::PollInput)->u64{
 let retained=input.budget.retained;let mut spent=Default::default();let mut work_units_spent=0;let mut semantic=false;
 let admitted=crate::operation_authority::with_actor_operation_authority(|identity|{let step=step_budget(retained,input.budget.fuel,input.budget.deadline_us)?;if outputs_held(){return Err(busy())}let call=with_entry(|entry|entry.dispatch_value_step(retained,step,&mut spent,original_job_clock,|cx|crate::plugin_runtime::drive_self_waking_ready(crate::reactor::poll_kernel(runtime,input.events,input.command_page,input.cold_pair_page,input.budget,identity,cx))))?;spent=call.receipt_spent;work_units_spent=call.work_units_spent;match call.result{Ok(mut output)=>{output.fuel_used=work_units_spent;ORIGINAL_OWNED_OUTPUT.with(|pending|**pending.borrow_mut()=Some(output));call.input.return_original(spent)?;Ok(())},Err(OriginalActorEntryFailure::Authority(error))=>Err(error),Err(OriginalActorEntryFailure::Semantic)=>{semantic=true;Ok(())}}});
 match admitted{Err(error)=>return_fixed(OriginalActorFixedCall{input:retained,spent,work_units_spent,kind:OriginalActorFixedKind::Failure{authority:Some(error.kind)}}),Ok(())if semantic=>return_fixed(OriginalActorFixedCall{input:retained,spent,work_units_spent,kind:OriginalActorFixedKind::Failure{authority:None}}),Ok(())=>ORIGINAL_OWNED_OUTPUT.with(|pending|{let pending=pending.borrow();crate::owned_abi::return_json(&Ok::<_,()>(pending.as_ref().unwrap()))})}
}

fn original_job_clock()->Option<u64>{crate::component::wasip2::semio::framework::pure::operation_clock_us()}
fn job_budget(budget:JobsWire::JobBudget)->Result<kernel::OriginalJobBudget,ValueError>{Ok(kernel::OriginalJobBudget{input:native_input(budget.input)?,fuel:budget.fuel,deadline_us:budget.deadline_us,cancelled:budget.cancelled})}
fn job_failure(failure:OriginalActorEntryFailure)->kernel::OriginalJobCallFailure{match failure{OriginalActorEntryFailure::Authority(error)=>kernel::OriginalJobCallFailure::Authority(error.kind),OriginalActorEntryFailure::Semantic=>kernel::OriginalJobCallFailure::Semantic}}
fn wire_job_failure(failure:kernel::OriginalJobCallFailure)->Wire::ActorCallFailure{match failure{kernel::OriginalJobCallFailure::Authority(error)=>Wire::ActorCallFailure::Authority(kind(error)),kernel::OriginalJobCallFailure::Semantic=>Wire::ActorCallFailure::Semantic}}
fn job_source(source:JobsWire::JobSource)->kernel::OriginalJobSource{kernel::OriginalJobSource{job:source.job,kind:source.kind,input:source.input,checkpoint:source.checkpoint}}
fn wire_job_source(source:kernel::OriginalJobSource)->JobsWire::JobSource{JobsWire::JobSource{job:source.job,kind:source.kind,input:source.input,checkpoint:source.checkpoint}}
/// 📥️ The actual job export retains its pending whole admission under the shared admitted actor entry.
pub fn start_job_original(mut source:Option<kernel::OriginalJobSource>,budget:kernel::OriginalJobBudget)->kernel::OriginalJobStartReply{
 let input=budget.input;let mut spent=Default::default();let result=with_entry(|entry|entry.dispatch_job_start_step(input,budget.step_budget(),&mut spent,original_job_clock,&mut source,|source,cx|{if budget.cancelled{if !original_cancel_flag_step(cx)?{return Ok(false)}return Err(ValueError::literal(ValueRefusalKind::Canceled,"original job admission cancelled before registered body birth"))}crate::reactor::jobs::abi::start(source,cx)}));
 match result{Ok(call)=>kernel::OriginalJobStartReply{input:call.input,spent:call.receipt_spent,work_units_spent:call.work_units_spent,admitted:call.result.as_ref().is_ok_and(|admitted|*admitted),returned_source:source,refusal:call.result.err().map(job_failure)},Err(error)=>kernel::OriginalJobStartReply{input,spent,work_units_spent:0,admitted:false,returned_source:source,refusal:Some(kernel::OriginalJobCallFailure::Authority(error.kind))}}
}
fn original_job_binding(job:u64,input:RetainedTurnInput)->Result<(),ValueRefusalKind>{let identity=crate::reactor::jobs::original_job_identity(job).or_else(||with_entry(|entry|entry.original_job_output_identity().filter(|identity|identity.0==job).map(|identity|(identity.1,identity.2))).ok().flatten());match identity{None=>Err(ValueRefusalKind::InvalidValue),Some(identity)if identity!=(input.operation,input.generation)=>Err(ValueRefusalKind::OwnershipLimit),Some(_)=>Ok(())}}
fn original_cancel_flag_step(cx:&mut StepContext<'_>)->Result<bool,ValueError>{if cx.is_cancelled(){return Ok(true)}if cx.should_yield(){return Ok(false)}let Some(progress)=cx.borrowed_original_cancel_token()?.signal_cancelled_flag_step(cx.retained_grant())else{return Ok(false)};cx.consume_retained(progress)?;cx.consume_fuel(progress.copied_items as u64);Ok(false)}
/// ▶️ Optional output and source-close acknowledgement come from the same registered owner and context.
pub fn step_job_original(job:u64,budget:kernel::OriginalJobBudget)->kernel::OriginalJobStepReply<kernel::OriginalJobOutcome>{
 let input=budget.input;if let Err(kind)=original_job_binding(job,input){return kernel::OriginalJobStepReply{input,spent:Default::default(),work_units_spent:0,outcome:None,source_closed:false,refusal:Some(kernel::OriginalJobCallFailure::Authority(kind))}}let mut spent=Default::default();let mut outcome=None;let result=with_entry(|entry|{let call=entry.dispatch_job_step(job,input,budget.step_budget(),&mut spent,original_job_clock,|cx|{if budget.cancelled&&!original_cancel_flag_step(cx)?{return Ok(None)}crate::reactor::jobs::abi::step(job,cx)},|output,cx|{if budget.cancelled&&!matches!(output,crate::reactor::jobs::JobStep::Failed(_)){if !original_cancel_flag_step(cx)?{return Ok(false)}return Ok(false)}if cx.should_yield()||cx.retained_grant().maximum_items==0||cx.retained_grant().maximum_depth==0{return Ok(false)}let(state,bytes)=match output{crate::reactor::jobs::JobStep::Running(bytes)=>(kernel::OriginalJobOutputState::Running,bytes.as_deref().unwrap_or(&[])),crate::reactor::jobs::JobStep::Done(bytes)=>(kernel::OriginalJobOutputState::Done,&bytes[..]),crate::reactor::jobs::JobStep::Failed(bytes)=>(kernel::OriginalJobOutputState::Failed,&bytes[..])};cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);outcome=Some(kernel::OriginalJobOutcome{job,operation:input.operation,generation:input.generation,state,byte_length:bytes.len()as u64});Ok(false)});let closed=!entry.has_original_job_source()&&!entry.has_original_job_output()&&crate::reactor::jobs::original_job_identity(job).is_none();(call,closed)});
 match result{Ok((call,closed))=>{let refusal=match call.result{Ok(value)=>{assert!(value.is_none(),"original normal transport keeps its whole output in Entry custody");None},Err(error)=>{outcome=None;Some(job_failure(error))}};kernel::OriginalJobStepReply{input:call.input,spent:call.receipt_spent,work_units_spent:call.work_units_spent,outcome,source_closed:closed,refusal}},Err(error)=>kernel::OriginalJobStepReply{input,spent,work_units_spent:0,outcome:None,source_closed:false,refusal:Some(kernel::OriginalJobCallFailure::Authority(error.kind))}}
}
/// 📥️ One original bounded body page returns before the same source's paid closure acknowledgement.
pub fn read_job_output_original(job:u64,budget:kernel::OriginalJobBudget)->kernel::OriginalJobOutputReply{
 let input=budget.input;let matches=with_entry(|entry|entry.original_job_output_identity()==Some((job,input.operation,input.generation))).unwrap_or(false);if !matches{return kernel::OriginalJobOutputReply{input,spent:Default::default(),work_units_spent:0,chunk:None,source_closed:false,refusal:Some(kernel::OriginalJobCallFailure::Authority(ValueRefusalKind::OwnershipLimit))}}let mut spent=Default::default();let result=with_entry(|entry|entry.read_job_output_step(job,input,budget.step_budget(),&mut spent,original_job_clock,budget.cancelled));match result{Ok(call)=>{let(chunk,refusal)=match call.result{Ok(chunk)=>(Some(chunk),None),Err(error)=>(None,Some(job_failure(error)))};let source_closed=false;kernel::OriginalJobOutputReply{input:call.input,spent:call.receipt_spent,work_units_spent:call.work_units_spent,chunk,source_closed,refusal}},Err(error)=>kernel::OriginalJobOutputReply{input,spent,work_units_spent:0,chunk:None,source_closed:false,refusal:Some(kernel::OriginalJobCallFailure::Authority(error.kind))}}
}

/// 🤝️ Clears only the exact preborn offered identity after the caller receives its completed output.
pub fn acknowledge_job_output_original(job:u64,budget:kernel::OriginalJobBudget)->kernel::OriginalJobOutputAckReply{let input=budget.input;let mut spent=Default::default();let result=with_entry(|entry|entry.acknowledge_job_output_step(job,input,budget.step_budget(),&mut spent,original_job_clock));match result{Ok(call)=>{let acknowledged=call.result.as_ref().is_ok_and(|accepted|*accepted);let source_closed=acknowledged&&crate::reactor::jobs::original_job_identity(job).is_none();kernel::OriginalJobOutputAckReply{input:call.input,spent:call.receipt_spent,work_units_spent:call.work_units_spent,acknowledged,source_closed,refusal:call.result.err().map(job_failure)}},Err(error)=>kernel::OriginalJobOutputAckReply{input,spent,work_units_spent:0,acknowledged:false,source_closed:false,refusal:Some(kernel::OriginalJobCallFailure::Authority(error.kind))}}}

/// 🛑️ One original caller-funded cancellation admission precedes bounded source and body retirement.
pub fn cancel_job_original(job:u64,budget:kernel::OriginalJobBudget)->kernel::OriginalJobCancelReply{
 let input=budget.input;if let Err(kind)=original_job_binding(job,input){return kernel::OriginalJobCancelReply{input,spent:Default::default(),work_units_spent:0,admitted:false,refusal:Some(kernel::OriginalJobCallFailure::Authority(kind))}}let output_held=with_entry(|entry|entry.original_job_output_identity().is_some_and(|identity|identity==(job,input.operation,input.generation))).unwrap_or(false);let mut spent=Default::default();let result=with_entry(|entry|entry.dispatch_value_step(input,budget.step_budget(),&mut spent,original_job_clock,|cx|{if !original_cancel_flag_step(cx)?{return Ok(false)}if output_held{return Ok(true)}crate::reactor::jobs::abi::cancel(job,cx)}));
 match result{Ok(call)=>kernel::OriginalJobCancelReply{input:call.input,spent:call.receipt_spent,work_units_spent:call.work_units_spent,admitted:call.result.as_ref().is_ok_and(|admitted|*admitted),refusal:call.result.err().map(job_failure)},Err(error)=>kernel::OriginalJobCancelReply{input,spent,work_units_spent:0,admitted:false,refusal:Some(kernel::OriginalJobCallFailure::Authority(error.kind))}}
}
/// ♻️ Failed actor entry closes the same original jobs and their terminal payloads before actor authority teardown.
pub fn close_jobs_original(budget:kernel::OriginalJobBudget)->kernel::OriginalJobCancelReply{let input=budget.input;let mut spent=Default::default();let result=with_entry(|entry|entry.close_jobs_step(input,budget.step_budget(),&mut spent,original_job_clock,&mut crate::reactor::jobs::RegisteredOriginalActorJobs::borrow_original(input.operation,input.generation)));match result{Ok(call)=>kernel::OriginalJobCancelReply{input:call.input,spent:call.receipt_spent,work_units_spent:call.work_units_spent,admitted:call.result.as_ref().is_ok_and(|closed|*closed),refusal:call.result.err().map(job_failure)},Err(error)=>kernel::OriginalJobCancelReply{input,spent,work_units_spent:0,admitted:false,refusal:Some(kernel::OriginalJobCallFailure::Authority(error.kind))}}}
pub fn close_jobs_wit(budget:JobsWire::JobBudget)->JobsWire::JobCancelCall{let input=budget.input;match job_budget(budget){Ok(budget)=>{let reply=close_jobs_original(budget);JobsWire::JobCancelCall{input,spent:progress(reply.spent),work_units_spent:reply.work_units_spent,admitted:reply.admitted,refusal:reply.refusal.map(wire_job_failure)}},Err(error)=>JobsWire::JobCancelCall{input,spent:progress(Default::default()),work_units_spent:0,admitted:false,refusal:Some(Wire::ActorCallFailure::Authority(kind(error.kind)))}}}
pub fn start_job_wit(source:Option<JobsWire::JobSource>,budget:JobsWire::JobBudget)->JobsWire::JobStartCall{let input=budget.input;match job_budget(budget){Ok(budget)=>{let reply=start_job_original(source.map(job_source),budget);JobsWire::JobStartCall{input,spent:progress(reply.spent),work_units_spent:reply.work_units_spent,admitted:reply.admitted,returned_source:reply.returned_source.map(wire_job_source),refusal:reply.refusal.map(wire_job_failure)}},Err(error)=>JobsWire::JobStartCall{input,spent:progress(Default::default()),work_units_spent:0,admitted:false,returned_source:source,refusal:Some(Wire::ActorCallFailure::Authority(kind(error.kind)))}}}
fn wire_job_outcome(outcome:kernel::OriginalJobOutcome)->JobsWire::JobOutcome{JobsWire::JobOutcome{job:outcome.job,operation:outcome.operation,generation:outcome.generation,state:match outcome.state{kernel::OriginalJobOutputState::Running=>JobsWire::JobOutputState::Running,kernel::OriginalJobOutputState::Done=>JobsWire::JobOutputState::Done,kernel::OriginalJobOutputState::Failed=>JobsWire::JobOutputState::Failed},byte_length:outcome.byte_length}}
pub fn step_job_wit(job:u64,budget:JobsWire::JobBudget)->JobsWire::JobStepCall{let input=budget.input;match job_budget(budget){Ok(budget)=>{let reply=step_job_original(job,budget);JobsWire::JobStepCall{input,spent:progress(reply.spent),work_units_spent:reply.work_units_spent,outcome:reply.outcome.map(wire_job_outcome),source_closed:reply.source_closed,refusal:reply.refusal.map(wire_job_failure)}},Err(error)=>JobsWire::JobStepCall{input,spent:progress(Default::default()),work_units_spent:0,outcome:None,source_closed:false,refusal:Some(Wire::ActorCallFailure::Authority(kind(error.kind)))}}}
pub fn read_job_output_wit(job:u64,budget:JobsWire::JobBudget)->JobsWire::JobOutputCall{let input=budget.input;match job_budget(budget){Ok(budget)=>{let reply=read_job_output_original(job,budget);JobsWire::JobOutputCall{input,spent:progress(reply.spent),work_units_spent:reply.work_units_spent,chunk:reply.chunk.map(|chunk|JobsWire::JobOutputChunk{offset:chunk.offset,bytes:chunk.bytes,output_closed:chunk.output_closed}),source_closed:reply.source_closed,refusal:reply.refusal.map(wire_job_failure)}},Err(error)=>JobsWire::JobOutputCall{input,spent:progress(Default::default()),work_units_spent:0,chunk:None,source_closed:false,refusal:Some(Wire::ActorCallFailure::Authority(kind(error.kind)))}}}

pub fn acknowledge_job_output_wit(job:u64,budget:JobsWire::JobBudget)->JobsWire::JobOutputAckCall{let input=budget.input;match job_budget(budget){Ok(budget)=>{let reply=acknowledge_job_output_original(job,budget);JobsWire::JobOutputAckCall{input,spent:progress(reply.spent),work_units_spent:reply.work_units_spent,acknowledged:reply.acknowledged,source_closed:reply.source_closed,refusal:reply.refusal.map(wire_job_failure)}},Err(error)=>JobsWire::JobOutputAckCall{input,spent:progress(Default::default()),work_units_spent:0,acknowledged:false,source_closed:false,refusal:Some(Wire::ActorCallFailure::Authority(kind(error.kind)))}}}

pub fn cancel_job_wit(job:u64,budget:JobsWire::JobBudget)->JobsWire::JobCancelCall{let input=budget.input;match job_budget(budget){Ok(budget)=>{let reply=cancel_job_original(job,budget);JobsWire::JobCancelCall{input,spent:progress(reply.spent),work_units_spent:reply.work_units_spent,admitted:reply.admitted,refusal:reply.refusal.map(wire_job_failure)}},Err(error)=>JobsWire::JobCancelCall{input,spent:progress(Default::default()),work_units_spent:0,admitted:false,refusal:Some(Wire::ActorCallFailure::Authority(kind(error.kind)))}}}
